F = {}
_FCA = "Financial advice in the UK is regulated by the Financial Conduct Authority (FCA). Check that any adviser or firm is authorised, or is an appointed representative of an authorised firm, on the FCA register. If something goes wrong you can complain to the firm, then to the Financial Ombudsman Service, and the Financial Services Compensation Scheme may protect you if an authorised firm fails."
F['fa'] = dict(noun='financial adviser', nouns='financial advisers', practice='financial advice firm', hub='financial-advisors', group='finance',
 regulator=[_FCA, "Advisers must tell you whether their advice is independent (considering the whole market) or restricted (limited to certain products or providers), and how they charge. Chartered status from the Chartered Insurance Institute or the Personal Finance Society, and certifications such as CFP, show advanced qualifications."],
 scenarios=["investing a lump sum from savings, inheritance or a business sale","planning for retirement and pensions","protecting family income with life or income protection cover","reviewing scattered pensions and investments","planning for inheritance tax","financial planning around divorce","advice for business owners on extracting profits","an annual review of an existing plan"],
 prepare=["your goals in plain words, such as retiring at 60","income, outgoings and savings","pensions, investments and their latest statements","property and mortgage details","debts and other commitments","your attitude to risk and investment experience","family situation and dependants","any deadlines, such as a pension decision"],
 questions=["Are you FCA authorised, and is your advice independent or restricted?","What qualifications do you hold?","How do you charge for initial advice and ongoing service?","What will the ongoing service include each year?","How do you assess my attitude to risk and capacity for loss?","Which platforms or providers do you typically use, and why?","How will you report on performance?","What happens if I want to stop ongoing advice?"],
 fees=["Advisers often charge for initial advice, then an ongoing fee for reviews, which may be fixed or a percentage of the money they look after. Firms must set out charges clearly before advising you. iComply does not publish fees; the firm quotes you, POA.","Ask for charges in pounds as well as percentages, and check what the ongoing service includes. The FCA's Consumer Duty expects firms to provide fair value."],
 red_flags=["not on the FCA register, or a clone firm using a real firm's name","guaranteed high returns","pressure to transfer pensions or invest quickly","unregulated investments presented as safe","unclear or hidden charges"],
 timeline="A first meeting is often available within a week or two. A full recommendation usually follows after the adviser has gathered information and researched options, which can take a few weeks.",
 after="Once introduced, the firm will explain its services and charges, then complete a fact-find with you. Advice and responsibility sit with the authorised firm. iComply does not give financial advice. The value of investments can fall as well as rise.",
 faqs=[("What is the difference between independent and restricted advice?","Independent advisers consider products from across the market. Restricted advisers focus on certain products or providers. Both can give good advice; they must tell you which they offer."),("Is the first meeting free?","Many firms offer a free initial consultation to explain their service and charges. Formal advice is then charged as agreed in writing.")])
F['pension'] = dict(noun='pension adviser', nouns='pension advisers', practice='pension advice firm', hub='pension-advisors', group='finance',
 regulator=[_FCA, "Some pension decisions carry special rules. Advice on transferring out of a defined benefit (final salary) scheme above a set value must come from an adviser with pension transfer specialist permissions, and safeguarded benefits deserve particular care. Free, impartial guidance is available from Pension Wise for people over 50 with defined contribution pensions."],
 scenarios=["deciding how to take money from a pension at retirement","combining several old workplace pensions","weighing up an annuity against drawdown","a transfer value offered from a final salary scheme","checking whether retirement plans are on track","pension sharing on divorce","business owners using pensions in tax planning","making sure pension death benefits go to the right people"],
 prepare=["recent statements for every pension you hold","your state pension forecast from the government's Check your State Pension service","your target retirement age and income","other savings, investments and property","any guaranteed benefits or protected tax-free cash","your health, which can affect annuity rates","beneficiary nominations","any deadlines on transfer quotes"],
 questions=["Are you FCA authorised, and do you hold pension transfer permissions if needed?","How will you check for valuable guarantees in my existing pensions?","How do you charge, and is it different if I do not go ahead?","How do you model income in retirement?","What happens with ongoing advice and reviews?","How do you protect against pension scams?","What are the tax consequences of each option?","Can you explain annuity and drawdown risks side by side?"],
 fees=["Pension advice is usually charged as an initial fee, sometimes with an ongoing advice fee. Specialist transfer advice is often charged separately. iComply does not publish fees; the firm quotes you, POA.","Ask whether fees can be taken from the pension, and how that affects its value."],
 red_flags=["cold calls about your pension","offers to access a pension before age 55 (rising to 57 from 2028)","overseas investments or unusual schemes","pressure to transfer quickly","firms not on the FCA register"],
 timeline="Initial meetings are often available within a couple of weeks. Gathering information from pension providers can take several weeks, so start well before you need to make a decision.",
 after="Once introduced, the firm will agree terms and gather information from your providers. Advice and responsibility sit with the authorised firm. iComply does not give financial advice. The value of pensions and investments can fall as well as rise.",
 faqs=[("What is Pension Wise?","A free, impartial government-backed service offering guidance to people over 50 about their options for defined contribution pensions. It is guidance, not personal advice."),("Should I combine my pensions?","Sometimes it makes life simpler and cheaper, but some older pensions have valuable guarantees or low charges. An adviser checks before recommending a transfer.")])
F['equity'] = dict(noun='equity release adviser', nouns='equity release advisers', practice='equity release advice firm', hub='equity-release', group='finance',
 regulator=["Equity release advice is regulated by the FCA, and advisers must hold a specialist qualification. Check the firm on the FCA register. Most providers and advisers are members of the Equity Release Council, whose standards include a no-negative-equity guarantee and the right to stay in your home for life.","You will also need your own solicitor to explain the legal documents before you sign. Many advisers encourage you to involve family members in the discussion."],
 scenarios=["releasing money to clear an interest-only mortgage","helping children or grandchildren onto the property ladder","home improvements or adaptations","topping up retirement income","paying for care at home","comparing equity release with downsizing","a couple where one partner is younger","reviewing an existing lifetime mortgage"],
 prepare=["the estimated value of your home","any mortgage or debts secured on it","ages and health of everyone who will be on the plan","what the money is for","other savings, pensions and benefits","whether you want to leave an inheritance","family members you would like to involve","any plans to move in the future"],
 questions=["Are you FCA authorised and a member of the Equity Release Council?","Do you consider the whole market?","How are you paid, and when is any fee due?","How will interest roll up over time?","Can I make voluntary repayments?","What happens if I move or go into care?","How would this affect means-tested benefits?","What are the alternatives, such as downsizing or a retirement mortgage?"],
 fees=["Advisers may charge a fee, receive commission from the lender, or both; they must tell you which. Product fees, valuation fees and solicitor's fees can also apply. iComply does not publish fees; the adviser explains charges, POA.","Ask for the total cost over time, including how interest compounds, and get it in writing."],
 red_flags=["no Equity Release Council membership","pressure to decide quickly","no discussion of alternatives","no involvement of your own solicitor","advice that ignores benefits and inheritance"],
 timeline="A typical equity release case can take from several weeks to a few months, including advice, valuation, offer and legal work.",
 after="Once introduced, the adviser will explain options and gather information. Advice and responsibility sit with the authorised firm. iComply does not give financial advice. A lifetime mortgage is a loan secured against your home and will reduce the value of your estate.",
 faqs=[("Will I still own my home?","With a lifetime mortgage, yes. With a home reversion plan, you sell part or all of your home but keep the right to live there."),("Can I lose my home?","Plans meeting Equity Release Council standards give you the right to live in your home for life, as long as you keep to the terms.")])
F['insurance'] = dict(noun='insurance broker', nouns='insurance brokers', practice='insurance brokerage', hub='insurance-brokers', group='insurance',
 regulator=["Insurance brokers and intermediaries in the UK must be authorised by the FCA, or be appointed representatives of an authorised firm. Check them on the FCA register. Many brokers belong to the British Insurance Brokers' Association (BIBA), and some hold Chartered status from the Chartered Insurance Institute.","Brokers must understand your demands and needs, explain key policy features and exclusions, and tell you how they are paid. Complaints that are not resolved can go to the Financial Ombudsman Service."],
 scenarios=["a business needing liability, property or specialist cover","renewal prices that have jumped","a claim history or unusual risk that standard insurers decline","new premises, vehicles or staff","personal protection such as life or income protection","high-value homes or contents","cover for an event, project or contract","a review of whether current cover is adequate"],
 prepare=["a description of what needs insuring","your current policy documents and renewal date","claims history for the past five years","values of property, stock or vehicles","turnover and staff numbers, for business cover","any contract requirements for cover","health information, for personal protection","what is most important to you, such as cover limits or cost"],
 questions=["Are you FCA authorised, and how are you paid?","How many insurers do you approach for a risk like mine?","What are the key exclusions in the cover you recommend?","Will you help if I need to make a claim?","How do you handle mid-term changes?","Is the sum insured adequate, and how was it worked out?","What happens if I disclose something incorrectly?","Do you offer premium finance, and what does it cost?"],
 fees=["Brokers are often paid commission by the insurer and sometimes charge a broker fee; they must disclose how they are paid if you ask. Premiums are set by insurers based on risk. iComply does not publish prices; the broker quotes you, POA.","Compare cover, excesses and exclusions, not just the premium. The cheapest policy is not always the best value when you need to claim."],
 red_flags=["not on the FCA register","reluctance to explain exclusions","pressure to skip disclosures","no help offered at claim time","unclear fees or commissions"],
 timeline="Straightforward quotes can often be arranged within days. Complex business risks or specialist cover may take a few weeks while insurers review information, so start before your renewal date.",
 after="Once introduced, the broker will gather information and approach insurers. Advice and responsibility sit with the authorised broker. iComply does not arrange insurance.",
 faqs=[("Is a broker more expensive than buying direct?","Not necessarily. Brokers can access insurers and schemes not available directly, and help with claims. The right choice depends on how complex your needs are."),("What is non-disclosure?","Failing to tell an insurer something relevant. It can reduce or void a claim, so answer questions fully and ask your broker if unsure.")])
